-- =============================================================================
-- Agorbis · 0085 · Municipios de Brasil como nivel 4 (D137)
-- -----------------------------------------------------------------------------
-- BORRADOR, NO APLICAR. Vive en supabase/sql-drafts/ hasta que el responsable
-- lo promueva; el número es provisional.
--
-- Generado por scripts/build-brasil-level4-draft.mjs; no se edita a mano.
--
-- Va después de 0076 y de los borradores de Uruguay a Venezuela.
--
-- Fuente: API de localidades del IBGE (servicodados.ibge.gov.br, datos
-- públicos del Estado brasileño, con atribución), consultada el 2026-11-21.
-- 5569 municipios bajo sus 26 estados; el Distrito Federal no tiene
-- municipios y queda en su nivel 3, como Fernando de Noronha, distrito
-- estadual sin prefeitura. Sin coordenadas: el GPS del onboarding sugiere
-- el estado.
-- =============================================================================

begin;

set local search_path = '';

create temporary table level4_rows (
  slug text primary key,
  name text not null,
  parent_slug text not null,
  description text not null,
  lat double precision,
  lng double precision
) on commit drop;


-- Falla cerrado: si el esquema o los datos no son los que se revisaron, no
-- inserta nada en vez de dejar una carga a medias.
do $guard$
declare
  v_missing text;
begin
  select string_agg(distinct i.parent_slug, ', ') into v_missing
  from pg_temp.level4_rows i
  where not exists (
    select 1 from public.communities p
    where p.slug = i.parent_slug and p.level = 3
      and p.path = 'earth.south-america.brasil.' || p.slug
  );
  if v_missing is not null then
    raise exception 'AGORBIS_0085_MISSING_STATE: %', v_missing;
  end if;

  select string_agg(i.slug, ', ') into v_missing
  from pg_temp.level4_rows i
  join public.communities c on c.slug = i.slug;
  if v_missing is not null then
    raise exception 'AGORBIS_0085_SLUG_TAKEN: %', v_missing;
  end if;
end;
$guard$;

select i.slug, i.name, 4::smallint, p.id, p.path || '.' || i.slug, '🗺️', i.description, i.lat, i.lng
from pg_temp.level4_rows i
join public.communities p on p.slug = i.parent_slug;

do $check$
declare
  v_expected_level4 constant int := 5569;
  v_level4 int;
begin
  select count(*) into v_level4 from public.communities
  where level = 4 and path like 'earth.south-america.brasil.%';
  if v_level4 <> v_expected_level4 then
    raise exception 'AGORBIS_0085_UNEXPECTED_TOTALS: nivel 4 %', v_level4;
  end if;
end;
$check$;

-- "on commit drop" no alcanza si otro borrador va en la misma transacción.
drop table pg_temp.level4_rows;

commit;
